setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" }
  CREATE CONCEPT ?dark { TYPE "Option" NAME "Dark" }
  CREATE CONCEPT ?note { TYPE "Note" NAME "A note" }
  CREATE CONCEPT ?citing {
    TYPE "Note"
    NAME "Citing note"
    SET STRUCTURAL { ("evidence", ?note) }
  }
  ENSURE PROPOSITION ?p (?alice, "prefers", ?dark)
  CREATE EVIDENCE ?e {
    SET FIELDS {
      evidence_class: "user_statement",
      payload: "I prefer dark mode.",
      content_digest: "sha3-256:d1ge5t",
      media_type: "text/plain",
      observed_at: "2026-08-16T09:00:00.000Z"
    }
  }
  CREATE ASSERTION ?a {
    SET FIELDS { proposition: ?p, asserted_by: ?alice, stance: "support", mode: "stated", confidence: 0.9 }
    SET STRUCTURAL { ("evidence", ?e) {role: "support"} }
  }
  CREATE ACTIVITY ?run {
    SET FIELDS {activity_class: "semantic_consolidation", status: "completed"}
    SET STRUCTURAL {
      ("inputs", ?alice)
      ("outputs", ?dark)
      ("associated_actors", ?alice)
      ("reviewed", ?note)
    }
  }
}
